	Es6RewriteModules_GOOG_MODULE_GET = QualifiedName_of("goog.module.get")
	Es6RewriteModules_GOOG_FORWARDDECLARE = QualifiedName_of("goog.forwardDeclare")
	Es6RewriteModules_GOOG_DECLAREMODULEID = QualifiedName_of("goog.declareModuleId")

