func (this *Es6RewriteModules_RewriteRequiresForEs6Modules) rewrite(scriptNode Node) {
	this.renameTable = SimpleTable_create()
	NodeTraversal_traverse(this.outer_.compiler_, scriptNode, icast_NodeTraversal_Callback(obj_(this)))
	if !this.renameTable.isEmpty() {
		NodeTraversal_traverse(this.outer_.compiler_, scriptNode, icast_NodeTraversal_Callback(obj_(new_Es6RenameTypeReferences(this.renameTable))))
	}
}

func (this *Es6RewriteModules_RewriteRequiresForEs6Modules) visit_impl(t *NodeTraversal, n Node, parent Node) {
	if !n.isCall() {
		return
	}
	var callTarget Node = n.getFirstChild()
	if !callTarget.isGetProp() {
		return
	}
	var isRequire bool = Es6RewriteModules_GOOG_REQUIRE.matches(callTarget)
	var isRequireType bool = Es6RewriteModules_GOOG_REQUIRETYPE.matches(callTarget)
	var isGet bool = Es6RewriteModules_GOOG_MODULE_GET.matches(callTarget)
	var isForwardDeclare bool = Es6RewriteModules_GOOG_FORWARDDECLARE.matches(callTarget)
	if ((!isRequire && !isRequireType) && !isGet) && !isForwardDeclare {
		return
	}
	if !n.hasTwoChildren() || !n.getLastChild().isStringLit() {
		return
	}
	var name string = n.getLastChild().getString()
	var moduleMetadata *ModuleMetadataMap_ModuleMetadata = cast_[*ModuleMetadataMap_ModuleMetadata](Map_get_s(this.outer_.moduleMetadataMap.getModulesByGoogNamespace(), name))
	if (moduleMetadata == nil) || !moduleMetadata.isEs6Module() {
		return
	}
	if isRequire {
		var currentModuleMetadata *ModuleMetadataMap_ModuleMetadata = cast_[*ModuleMetadataMap_ModuleMetadata](Map_get_s(this.outer_.moduleMetadataMap.getModulesByPath(), t.getInput().getPath().toString()))
		if (currentModuleMetadata != nil) && currentModuleMetadata.isEs6Module() {
			t.report(n, Es6RewriteModules_SHOULD_IMPORT_ES6_MODULE, []string{})
		}
	}
	if isGet && t.inGlobalHoistScope() {
		return
	}
	var statementNode Node = NodeUtil_getEnclosingStatement(n)
	var importHasAlias bool = NodeUtil_isNameDeclaration(statementNode)
	if importHasAlias {
		if statementNode.getFirstChild().isDestructuringLhs() {
			if isForwardDeclare {
				t.report(n, ClosurePrimitiveErrors_INVALID_DESTRUCTURING_FORWARD_DECLARE, []string{})
				return
			}
			if isRequireType {
				if !statementNode.isConst() {
					t.report(statementNode, Es6RewriteModules_REQUIRE_TYPE_FOR_ES6_SHOULD_BE_CONST, []string{})
					return
				}
				{
					var child Node = statementNode.getFirstFirstChild().getFirstChild()
					for ; child != 0; child = child.getNext() {
						Preconditions_checkState(child.isStringKey())
						Preconditions_checkState(child.getFirstChild().isName())
						this.renameTable.put(t.getScopeRoot().box_(), strobj_(child.getFirstChild().getString()), strobj_(ModuleRenaming_getGlobalName_ModuleMetadata_Optional(moduleMetadata, Optional_of[string](name)).getprop(child.getString()).join().orElse(nullstr_)))
					}
				}
			} else {
				{
					var child Node = statementNode.getFirstFirstChild().getFirstChild()
					for ; child != 0; child = child.getNext() {
						Preconditions_checkState(child.isStringKey())
						Preconditions_checkState(child.getFirstChild().isName())
						var globalName *ModuleRenaming_GlobalizedModuleName = this.outer_.getGlobalNameAndType(moduleMetadata, Optional_of[string](name), false).getprop(child.getString())
						var constNode Node = this.outer_.astFactory_.createSingleConstNameDeclaration(child.getFirstChild().getString(), globalName.toQname(this.outer_.astFactory_))
						constNode.srcrefTree(child)
						constNode.insertBefore(statementNode)
					}
				}
			}
			statementNode.detach()
			t.reportCodeChange()
		} else {
			if isForwardDeclare || isRequireType {
				if !statementNode.isConst() {
					var diagnostic *DiagnosticType = func() *DiagnosticType {
						if isForwardDeclare {
							return Es6RewriteModules_FORWARD_DECLARE_FOR_ES6_SHOULD_BE_CONST
						}
						return Es6RewriteModules_REQUIRE_TYPE_FOR_ES6_SHOULD_BE_CONST
					}()
					t.report(statementNode, diagnostic, []string{})
					return
				}
				this.renameTable.put(t.getScopeRoot().box_(), strobj_(statementNode.getFirstChild().getString()), strobj_(ModuleRenaming_getGlobalName_ModuleMetadata_Optional(moduleMetadata, Optional_of[string](name)).join().orElse(nullstr_)))
				statementNode.detach()
				t.reportCodeChange()
			} else {
				n.replaceWith(this.outer_.astFactory_.createName(ModuleRenaming_getGlobalName_ModuleMetadata_Optional(moduleMetadata, Optional_of[string](name)).getRoot(), AstFactory_type_Node(n)).srcrefTree(n))
				t.reportCodeChange()
			}
		}
	} else {
		if isForwardDeclare || isRequireType {
			this.renameTable.put(t.getScopeRoot().box_(), strobj_(name), strobj_(ModuleRenaming_getGlobalName_ModuleMetadata_Optional(moduleMetadata, Optional_of[string](name)).join().orElse(nullstr_)))
			statementNode.detach()
		} else {
			if statementNode.isExprResult() && (statementNode.getFirstChild() == n) {
				statementNode.detach()
			} else {
				n.replaceWith(this.outer_.astFactory_.createName(ModuleRenaming_getGlobalName_ModuleMetadata_Optional(moduleMetadata, Optional_of[string](name)).getRoot(), AstFactory_type_Node(n)).srcrefTree(n))
			}
		}
		t.reportCodeChange()
	}
}

type Es6RewriteModules_RenameGlobalVars struct {
	NodeTraversal_AbstractPostOrderCallback
	outer_     *Es6RewriteModules
	thisModule *Module
}

func (this *Es6RewriteModules_RenameGlobalVars) up_NodeTraversal_AbstractPostOrderCallback() *NodeTraversal_AbstractPostOrderCallback {
	if this == nil {
		return nil
	}
	return &this.NodeTraversal_AbstractPostOrderCallback
}

func (this *Es6RewriteModules_RenameGlobalVars) init_Es6RewriteModules_RenameGlobalVars(thisModule *Module) {
	this.NodeTraversal_AbstractPostOrderCallback.init_NodeTraversal_AbstractPostOrderCallback()
	this.thisModule = thisModule
}

func new_Es6RewriteModules_RenameGlobalVars(outer_ *Es6RewriteModules, thisModule *Module) *Es6RewriteModules_RenameGlobalVars {
	this := &Es6RewriteModules_RenameGlobalVars{}
	this.self_ = this
	this.outer_ = outer_
	this.init_Es6RewriteModules_RenameGlobalVars(thisModule)
	return this
}

func (this *Es6RewriteModules_RenameGlobalVars) visit_impl(t *NodeTraversal, n Node, parent Node) {
	var info *JSDocInfo = n.getJSDocInfo()
	if info != nil {
		it_1 := foreach_(any(info.getTypeNodes()))
		for it_1.next() {
			var typeNode Node = Node_of_(it_1.v)
			this.fixTypeNode(t, typeNode)
		}
	}
	if n.isName() {
		var name string = n.getString()
		var var_ *Var = cast_[*Var](t.getScope().getVar(name).self())
		if (var_ != nil) && var_.isGlobal() {
			var newName OptionalOf[string] = ModuleRenaming_getGlobalNameOfEsModuleLocalVariable(this.thisModule.metadata(), Optional_of[string](name)).join()
			n.setString(newName.get())
			n.setOriginalName(name)
			t.reportCodeChange_1(n)
			if NodeUtil_isDeclarationLValue(n) {
				this.outer_.declareGlobalVariable(n, t)
			}
		} else if (var_ == nil) && Map_containsKey_s(this.thisModule.boundNames(), name) {
			this.outer_.maybeAddAliasToSymbolTable(n, t.getSourceName())
			var binding *Binding = cast_[*Binding](Map_get_s(this.thisModule.boundNames(), name))
			var replacement Node = this.replace(n, binding)
			if ((replacement.isName() && parent.isCall()) && (parent.getFirstChild() == n)) && parent.getBooleanProp(Node_FREE_CALL) {
				parent.putBooleanProp(Node_FREE_CALL, true)
			}
			if NodeUtil_isDeclarationLValue(n) {
				this.outer_.declareGlobalVariable(n, t)
			}
			t.reportCodeChange()
		}
	}
}

func (this *Es6RewriteModules_RenameGlobalVars) replace(n Node, binding *Binding) Node {
	Preconditions_checkState(n.isName())
	for (binding.isModuleNamespace() && binding.metadata().isEs6Module()) && n.getParent().isGetProp() {
		var propertyName string = n.getParent().getString()
		var m *Module = this.outer_.moduleMap.getModule(binding.metadata().path())
		if Map_containsKey_s(m.namespace(), propertyName) {
			binding = cast_[*Binding](Map_get_s(m.namespace(), propertyName))
			n = n.getParent()
		} else {
			break
		}
	}
	var globalName *QualifiedName = ModuleRenaming_getGlobalName_Binding(binding)
	var newNode Node
	if !globalName.isSimple() {
		var root string = globalName.getRoot()
		newNode = func() Node {
			if (this.outer_.globalTypedScope != nil) && this.outer_.globalTypedScope.hasSlot(root) {
				return this.outer_.astFactory_.createQNameUsingJSTypeInfo(this.outer_.globalTypedScope, globalName.join().get())
			}
			return this.outer_.astFactory_.createQNameWithUnknownType(globalName.join().get())
		}()
	} else {
		newNode = this.outer_.astFactory_.createName(globalName.getRoot(), AstFactory_type_Node(n))
	}
	n.replaceWith(newNode)
	newNode.srcrefTree(n)
	newNode.setOriginalName(n.getString())
	return newNode
}

func (this *Es6RewriteModules_RenameGlobalVars) fixTypeNode(t *NodeTraversal, typeNode Node) {
	if typeNode.isStringLit() {
		var thisModule *Module = this.outer_.moduleMap.getModule(t.getInput().getPath())
		var name string = typeNode.getString()
		var splitted []string = sliceImm_(tc_string, Es6RewriteModules_DOT_SPLITTER.splitToList(strobj_(name)))
		var baseName string = sliceAt_(splitted, 0)
		var rest string = ""
		if int32(len(splitted)) > 1 {
			rest = String_substring_int(name, String_length(baseName))
		}
		var var_ *Var = cast_[*Var](t.getScope().getVar(baseName).self())
		if (var_ != nil) && var_.isGlobal() {
			this.maybeSetNewName(t, typeNode, name, (sstr_(ModuleRenaming_getGlobalNameOfEsModuleLocalVariable(thisModule.metadata(), Optional_of[string](baseName)).join().orElse("null")) + sstr_(rest)))
		} else if (var_ == nil) && Map_containsKey_s(thisModule.boundNames(), baseName) {
			var binding *Binding = cast_[*Binding](Map_get_s(thisModule.boundNames(), baseName))
			var globalName OptionalOf[string] = ModuleRenaming_getGlobalNameForJsDoc(this.outer_.moduleMap, binding, sliceView_(tc_string, splitted).subList(1, int32(len(splitted))))
			this.maybeSetNewName(t, typeNode, name, globalName.get())
			if this.outer_.preprocessorSymbolTable != nil {
				var onlyBaseName Node = Node_newString_String(baseName).srcref(typeNode)
				onlyBaseName.setLength(String_length(baseName))
				this.outer_.maybeAddAliasToSymbolTable(onlyBaseName, t.getSourceName())
			}
		}
		typeNode.setOriginalName(name)
	}
	{
		var child Node = typeNode.getFirstChild()
		for ; child != 0; child = child.getNext() {
			this.fixTypeNode(t, child)
		}
	}
}

func (this *Es6RewriteModules_RenameGlobalVars) maybeSetNewName(t *NodeTraversal, node Node, name string, newName string) {
	if !(name == newName) {
		node.setString(newName)
		node.setOriginalName(name)
		t.reportCodeChange()
	}
}

